using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;
namespace LWS.TruckSports {
// Explicit development-only Camera.Render + alpha-composited UI evidence, never a player-window/performance claim.
public static class SportsControlledCapture {
 public static void Save(SportsEventSession match,int width,int height,string path,Action<Camera> inspect=null)=>Save(match.menus.GetComponent<Canvas>(),match.cameras,width,height,path,inspect);
 public static void Save(Canvas canvas,Camera[] cameras,int width,int height,string path,Action<Camera> inspect=null){var mode=canvas.renderMode;var originalCamera=canvas.worldCamera;float distance=canvas.planeDistance,scale=canvas.scaleFactor;var scaler=canvas.GetComponent<CanvasScaler>();bool scaling=scaler.enabled;var transforms=canvas.GetComponentsInChildren<Transform>(true);var layers=transforms.Select(t=>t.gameObject.layer).ToArray();var active=RenderTexture.active;var rt=RenderTexture.GetTemporary(width,height,24,RenderTextureFormat.ARGB32);var ui=new GameObject("Owned controlled UI render camera").AddComponent<Camera>();ui.cullingMask=1<<5;ui.clearFlags=CameraClearFlags.SolidColor;ui.backgroundColor=Color.clear;ui.transform.position=new Vector3(0,1000,-1000);ui.orthographic=true;ui.nearClipPlane=.1f;ui.farClipPlane=50;ui.targetTexture=rt;Texture2D world=null,foreground=null;try{for(int i=0;i<transforms.Length;i++)transforms[i].gameObject.layer=5;scaler.enabled=false;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=ui;canvas.planeDistance=10;canvas.scaleFactor=Mathf.Min(width/1920f,height/1080f);Canvas.ForceUpdateCanvases();foreach(var camera in cameras){if(!camera.enabled)continue;var old=camera.targetTexture;float aspect=camera.aspect,ortho=camera.orthographicSize;var position=camera.transform.position;var rotation=camera.transform.rotation;try{camera.targetTexture=rt;camera.aspect=width*camera.rect.width/(height*camera.rect.height);var fit=camera.GetComponent<SportsCameraFit>();if(fit!=null)fit.Apply();camera.Render();}finally{camera.targetTexture=old;camera.aspect=aspect;camera.orthographicSize=ortho;camera.transform.SetPositionAndRotation(position,rotation);}}RenderTexture.active=rt;world=new Texture2D(width,height,TextureFormat.RGBA32,false);world.ReadPixels(new Rect(0,0,width,height),0,0);world.Apply();ui.Render();inspect?.Invoke(ui);RenderTexture.active=rt;foreground=new Texture2D(width,height,TextureFormat.RGBA32,false);foreground.ReadPixels(new Rect(0,0,width,height),0,0);foreground.Apply();var front=foreground.GetPixels32();var back=world.GetPixels32();for(int i=0;i<front.Length;i++)back[i]=Color32.Lerp(back[i],front[i],front[i].a/255f);foreground.SetPixels32(back);foreground.Apply();Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,foreground.EncodeToPNG());}finally{canvas.renderMode=mode;canvas.worldCamera=originalCamera;canvas.planeDistance=distance;canvas.scaleFactor=scale;scaler.enabled=scaling;for(int i=0;i<transforms.Length;i++)transforms[i].gameObject.layer=layers[i];RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);if(world!=null)UnityEngine.Object.Destroy(world);if(foreground!=null)UnityEngine.Object.Destroy(foreground);UnityEngine.Object.Destroy(ui.gameObject);}}
}
}
